      rewrite HA. exact (srun_sound tm true true cho1_1RB1RB_0LC1RD_0LB1LA_1LB0RD O1_1RB1RB_0LC1RD_0LB1LA_1LB0RD0 O1_1RB1RB_0LC1RD_0LB1LA_1LB0RD1 0 8
