(** ** The lap *)

Lemma lap_1RB1RB_0LC1RD_0LB1LA_1LB0RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RB_0LC1RD_0LB1LA_1LB0RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    exact (lapo_1RB1RB_0LC1RD_0LB1LA_1LB0RD p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1RB_0LC1RD_0LB1LA_1LB0RD : stepn tmm_1RB1RB_0LC1RD_0LB1LA_1LB0RD 13 InitES = Some (lift (Cc 1)).
