  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1RB_0LC1RD_0LB1LA_1LB0RD : existsb (fun tg => cfires tmm_1RB1RB_0LC1RD_0LB1LA_1LB0RD c0 13 tg) pins_1RB1RB_0LC1RD_0LB1LA_1LB0RD = true.
