(** ** The lap *)

Lemma lap_1RB____0LC1RB_0LB1RD_1LC0RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
