Definition mk_1RB0RB_0RC0LD_0RD0RA_1LD1RB (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0RB_0RC0LD_0RD0RA_1LD1RB.

(** 1RB0RB_0RC0LD_0RD0RA_1LD1RB *)
(** 1RB0RB_0RC0LD_0RD0RA_1LD1RB -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RB_0RC0LD_0RD0RA_1LD1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StB
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S0 DR StA
  | StD, S0 => mk S1 DL StD | StD, S1 => mk S1 DR StB end.

(** Its mirror 1LB0LB_0LC0RD_0LD0LA_1RD1LB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0RB_0RC0LD_0RD0RA_1LD1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DL StB
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S0 DL StA
  | StD, S0 => mk S1 DR StD | StD, S1 => mk S1 DL StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0RB_0RC0LD_0RD0RA_1LD1RB : list Instr := [(StA, S0)].
Definition tmw_1RB0RB_0RC0LD_0RD0RA_1LD1RB : TM := tm_wrap_trs tmm_1RB0RB_0RC0LD_0RD0RA_1LD1RB pins_1RB0RB_0RC0LD_0RD0RA_1LD1RB.
Local Notation tm := tmw_1RB0RB_0RC0LD_0RD0RA_1LD1RB.

Lemma mirror_ok_1RB0RB_0RC0LD_0RD0RA_1LD1RB : mirror_tm tm_1RB0RB_0RC0LD_0RD0RA_1LD1RB = tmm_1RB0RB_0RC0LD_0RD0RA_1LD1RB.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0RB_0RC0LD_0RD0RA_1LD1RB (p : positive) : cconf := (StD, (Ap_Alph_111_101_1 p ++ [S0], S0, [S0;S1])).
Local Notation Cc := Cc_1RB0RB_0RC0LD_0RD0RA_1LD1RB.

(** ** The certificate *)

Definition A0_1RB0RB_0RC0LD_0RD0RA_1LD1RB : sconf := mkC StD (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition A1_1RB0RB_0RC0LD_0RD0RA_1LD1RB : sconf := mkC StD (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition chi_1RB0RB_0RC0LD_0RD0RA_1LD1RB : list lstep := [SWin 6; SCycL 3 0; SWin 4; SCycR 3].

Lemma run_int_1RB0RB_0RC0LD_0RD0RA_1LD1RB : srun tm false true chi_1RB0RB_0RC0LD_0RD0RA_1LD1RB A0_1RB0RB_0RC0LD_0RD0RA_1LD1RB = Some (A1_1RB0RB_0RC0LD_0RD0RA_1LD1RB, 6, 10).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB0RB_0RC0LD_0RD0RA_1LD1RB : sconf := mkC StD (mkS [] [S1;S0;S1] 1 0 [S1;S0]) S0 (mkS [S0;S1] [] 0 0 []).
Definition B1_1RB0RB_0RC0LD_0RD0RA_1LD1RB : sconf := mkC StD (mkS [] [S1;S1;S1] 1 1 [S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition cho_1RB0RB_0RC0LD_0RD0RA_1LD1RB : list lstep := [SWin 6; SCycL 3 0; SWin 2; SWinL 6; SCycR 3; SRotL 3; SFoldL 1].

Lemma run_ovf_1RB0RB_0RC0LD_0RD0RA_1LD1RB : srun tm true true cho_1RB0RB_0RC0LD_0RD0RA_1LD1RB B0_1RB0RB_0RC0LD_0RD0RA_1LD1RB = Some (B1_1RB0RB_0RC0LD_0RD0RA_1LD1RB, 6, 14).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0RB_0RC0LD_0RD0RA_1LD1RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_111_101_1 q0 ++ [S0]) [] j A0_1RB0RB_0RC0LD_0RD0RA_1LD1RB.
Proof.
  intros p j q0 E. destruct (Alph_111_101_1.cview_some_Alph_111_101_1 p j q0 E) as (H1 & _).
  unfold Cc_1RB0RB_0RC0LD_0RD0RA_1LD1RB, cden, A0_1RB0RB_0RC0LD_0RD0RA_1LD1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB0RB_0RC0LD_0RD0RA_1LD1RB : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_111_101_1 q0 ++ [S0]) [] j A1_1RB0RB_0RC0LD_0RD0RA_1LD1RB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_111_101_1.cview_some_Alph_111_101_1 p j q0 E) as (_ & H2).
  unfold Cc_1RB0RB_0RC0LD_0RD0RA_1LD1RB, cden, A1_1RB0RB_0RC0LD_0RD0RA_1LD1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0RB_0RC0LD_0RD0RA_1LD1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (6 * j + 10). split; [lia|].
  rewrite (gsi_1RB0RB_0RC0LD_0RD0RA_1LD1RB p j q0 E).
  rewrite (srun_sound tm false true chi_1RB0RB_0RC0LD_0RD0RA_1LD1RB A0_1RB0RB_0RC0LD_0RD0RA_1LD1RB A1_1RB0RB_0RC0LD_0RD0RA_1LD1RB 6 10
             run_int_1RB0RB_0RC0LD_0RD0RA_1LD1RB (Ap_Alph_111_101_1 q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB0RB_0RC0LD_0RD0RA_1LD1RB p j q0 E).
Qed.

Lemma gso_1RB0RB_0RC0LD_0RD0RA_1LD1RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RB_0RC0LD_0RD0RA_1LD1RB.
Proof.
  intros p j E. destruct (Alph_111_101_1.cview_none_Alph_111_101_1 p j E) as (H1 & _).
  unfold Cc_1RB0RB_0RC0LD_0RD0RA_1LD1RB, cden, B0_1RB0RB_0RC0LD_0RD0RA_1LD1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0RB_0RC0LD_0RD0RA_1LD1RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0RB_0RC0LD_0RD0RA_1LD1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RB_0RC0LD_0RD0RA_1LD1RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_111_101_1.cview_none_Alph_111_101_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RB_0RC0LD_0RD0RA_1LD1RB
             = (StD, (rep [S1;S1;S1] (S j) ++ [S1], S0, [S0;S1]))).
  { unfold cden, B1_1RB0RB_0RC0LD_0RD0RA_1LD1RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S1;S1] (S j) ++ [S1]) ++ [S0], S0, [S0;S1]))).
  { unfold Cc_1RB0RB_0RC0LD_0RD0RA_1LD1RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0RB_0RC0LD_0RD0RA_1LD1RB. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0RB_0RC0LD_0RD0RA_1LD1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RB_0RC0LD_0RD0RA_1LD1RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RB_0RC0LD_0RD0RA_1LD1RB B0_1RB0RB_0RC0LD_0RD0RA_1LD1RB B1_1RB0RB_0RC0LD_0RD0RA_1LD1RB 6 14 p j' [] []).
    + exact run_ovf_1RB0RB_0RC0LD_0RD0RA_1LD1RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RB_0RC0LD_0RD0RA_1LD1RB p j' E).
    + exact (geo_1RB0RB_0RC0LD_0RD0RA_1LD1RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0RB_0RC0LD_0RD0RA_1LD1RB : stepn tmm_1RB0RB_0RC0LD_0RD0RA_1LD1RB 4 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0RB_0RC0LD_0RD0RA_1LD1RB 4 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0RB_0RC0LD_0RD0RA_1LD1RB 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0RB_0RC0LD_0RD0RA_1LD1RB : existsb (fun tg => cfires tmm_1RB0RB_0RC0LD_0RD0RA_1LD1RB c0 4 tg) pins_1RB0RB_0RC0LD_0RD0RA_1LD1RB = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RB_0RC0LD_0RD0RA_1LD1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_0RC0LD_0RD0RA_1LD1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RB_0RC0LD_0RD0RA_1LD1RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RB_0RC0LD_0RD0RA_1LD1RB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RB_0RC0LD_0RD0RA_1LD1RB : forall t, ~ In t pins_1RB0RB_0RC0LD_0RD0RA_1LD1RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RB_0RC0LD_0RD0RA_1LD1RB.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RB_0RC0LD_0RD0RA_1LD1RB
      with (l := [SWin 6; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RB_0RC0LD_0RD0RA_1LD1RB
      with (l := [SWin 5]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RB_0RC0LD_0RD0RA_1LD1RB
      with (l := [SWin 3]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RB_0RC0LD_0RD0RA_1LD1RB
      with (l := [SWin 6; SCycL 3 0; SWin 2; SWinL 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RB_0RC0LD_0RD0RA_1LD1RB
      with (l := [SWin 6]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RB_0RC0LD_0RD0RA_1LD1RB
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RB_0RC0LD_0RD0RA_1LD1RB
      with (l := [SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_1RB0RB_0RC0LD_0RD0RA_1LD1RB : NonHalt tmm_1RB0RB_0RC0LD_0RD0RA_1LD1RB /\ QHBoundTr 32779478 tmm_1RB0RB_0RC0LD_0RD0RA_1LD1RB /\ QuasiHaltsTr tmm_1RB0RB_0RC0LD_0RD0RA_1LD1RB.
Proof.
  apply (lap_qh_stage tmm_1RB0RB_0RC0LD_0RD0RA_1LD1RB pins_1RB0RB_0RC0LD_0RD0RA_1LD1RB Cc 1 4 32779478).
  - exact bootq_1RB0RB_0RC0LD_0RD0RA_1LD1RB.
  - intros p _. apply lap_1RB0RB_0RC0LD_0RD0RA_1LD1RB.
  - intros t Ht p _. apply fire_1RB0RB_0RC0LD_0RD0RA_1LD1RB. exact Ht.
  - exact wit_1RB0RB_0RC0LD_0RD0RA_1LD1RB.
  - apply qcleb_CE_06. reflexivity.
Qed.

Theorem qhtr_1RB0RB_0RC0LD_0RD0RA_1LD1RB : NonHalt tm_1RB0RB_0RC0LD_0RD0RA_1LD1RB /\ QHBoundTr 32779478 tm_1RB0RB_0RC0LD_0RD0RA_1LD1RB /\ QuasiHaltsTr tm_1RB0RB_0RC0LD_0RD0RA_1LD1RB.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0RB_0RC0LD_0RD0RA_1LD1RB). rewrite mirror_ok_1RB0RB_0RC0LD_0RD0RA_1LD1RB. exact qhtrm_1RB0RB_0RC0LD_0RD0RA_1LD1RB. Qed.

End B_CE_06_013.

