Lemma geo_1RB0RB_0RC0LD_0RD0RA_1LD1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RB_0RC0LD_0RD0RA_1LD1RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_111_101_1.cview_none_Alph_111_101_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RB_0RC0LD_0RD0RA_1LD1RC
             = (StD, (rep [S1;S1;S1] (S j) ++ [S1], S0, [S1]))).
  { unfold cden, B1_1RB0RB_0RC0LD_0RD0RA_1LD1RC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S1;S1] (S j) ++ [S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_1RB0RB_0RC0LD_0RD0RA_1LD1RC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0RB_0RC0LD_0RD0RA_1LD1RC. reflexivity.
