(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RC_1RC1LD_0LB0RA_1RA1LB : forall (l0 l1 l2 l3 : list lstep) (t : Instr),
  srun_instr tm true true l0 O0_1RB0RC_1RC1LD_0LB0RA_1RA1LB0 = Some t ->
  srun_instr tm true true l1 O1_1RB0RC_1RC1LD_0LB0RA_1RA1LB0 = Some t ->
  srun_instr tm true true l2 O2_1RB0RC_1RC1LD_0LB0RA_1RA1LB0 = Some t ->
  srun_instr tm true true l3 O3_1RB0RC_1RC1LD_0LB0RA_1RA1LB0 = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l0 l1 l2 l3 t H0 H1 H2 H3 p j E.
  pose proof (Nat.div_mod_eq j 2) as Hd.
  pose proof (Nat.mod_upper_bound j 2 ltac:(discriminate)) as Hm.
  set (i := j / 2) in *. set (r := j mod 2) in *. clearbody i r.
  destruct r as [|[|r]]; [idtac | idtac | exfalso; lia].
  - destruct i as [|i].
    + assert (Ej : j = 0) by lia. subst j.
      destruct (gopar1_1RB0RC_1RC1LD_0LB0RA_1RA1LB p E) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l1 O1_1RB0RC_1RC1LD_0LB0RA_1RA1LB0 p 0 [] [] t
               H1 ltac:(reflexivity) ltac:(reflexivity) HA).
    + destruct (gopar0_1RB0RC_1RC1LD_0LB0RA_1RA1LB p j i E ltac:(lia)) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l0 O0_1RB0RC_1RC1LD_0LB0RA_1RA1LB0 p i [] [] t
               H0 ltac:(reflexivity) ltac:(reflexivity) HA).
  - destruct i as [|i].
    + assert (Ej : j = 1) by lia. subst j.
      destruct (gopar3_1RB0RC_1RC1LD_0LB0RA_1RA1LB p E) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l3 O3_1RB0RC_1RC1LD_0LB0RA_1RA1LB0 p 0 [] [] t
               H3 ltac:(reflexivity) ltac:(reflexivity) HA).
    + destruct (gopar2_1RB0RC_1RC1LD_0LB0RA_1RA1LB p j i E ltac:(lia)) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l2 O2_1RB0RC_1RC1LD_0LB0RA_1RA1LB0 p i [] [] t
               H2 ltac:(reflexivity) ltac:(reflexivity) HA).
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RC_1RC1LD_0LB0RA_1RA1LB : forall t, ~ In t pins_1RB0RC_1RC1LD_0LB0RA_1RA1LB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
